}

void end_level_infinity_mode_case_init(variable_t *sf)
{
    sfTime pause = sfSeconds(1.0);

    display_level(sf);
    sfSleep(pause);
    sf->var_norm.obstacle_touch = 0;
    sf->var_norm.slow_dino = 0;
    sf->var_norm.dino_jump = 0;
    sf->var_norm.dino_down_two = -2;
    sf->vector.dino.x = 30;
    sf->vector.dino.y = 638;
