    while (sf->vector.select.y > 0) {
        sf->time.menu = sfClock_getElapsedTime(sf->clock.menu);
        seconds = sf->time.menu.microseconds / 1000000.0;
        if (seconds >= 0.014) {
            sf->vector.bg_highscore.y -= 50;
            sf->vector.select.y -= 50;
